import{_ as o,o as a,c,ai as p}from"./chunks/framework.Ba-VnP44.js";const _=JSON.parse('{"title":"项目管理系统 · OpenBiz 第三个独立消费者","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/pms.md","filePath":"apps/openbiz/pms.md"}'),d={name:"apps/openbiz/pms.md"};function i(n,e,r,t,s,l){return a(),c("div",null,[...e[0]||(e[0]=[p('<h1 id="项目管理系统-·-openbiz-第三个独立消费者" tabindex="-1">项目管理系统 · OpenBiz 第三个独立消费者 <a class="header-anchor" href="#项目管理系统-·-openbiz-第三个独立消费者" aria-label="Permalink to “项目管理系统 · OpenBiz 第三个独立消费者”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-pms-app</code>（<code>E:/8.cangku/for-job/openbiz-pms-app</code>）：独立后端（端口 18083）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_pms</code>。</p></blockquote><blockquote><p>实证：OpenBiz 母仓无 PMS 域，按 OpenBiz 命名约定自建 <code>openbiz_pms_*</code> 表，在其多租户基座之上实现「项目 + 任务 / 里程碑 + 看板」最小闭环。验证 OpenBiz V0.2「更多独立 consumer」目标。</p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户（TenantContext / TenantService / 自动装配）、RuoYi 登录外壳</li><li><strong>自建</strong>：<code>openbiz_pms_project</code> / <code>openbiz_pms_task</code> 表 + Mapper / Service / Controller <ul><li>项目状态机：<code>PLANNING → ACTIVE → COMPLETED</code>，<code>ACTIVE ⇄ ON_HOLD</code>，活动态 <code>→ CANCELLED</code></li><li>任务状态机：<code>TODO → IN_PROGRESS → DONE</code>，活动态 <code>→ CANCELLED</code>，<code>DONE → IN_PROGRESS</code>（重开）</li><li>里程碑：<code>type=MILESTONE</code> 与 <code>TASK</code> 共用一张表</li><li>看板：<code>GET /api/pms/projects/{id}/board</code> 按状态分组，对应 Kanban 视图</li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>创建(<code>PLANNING</code>) → 启动(<code>ACTIVE</code>) → 建任务(<code>TODO</code>) → 开始(<code>IN_PROGRESS</code>) → 完成(<code>DONE</code>) → 看板分组正确 → 完成项目(<code>COMPLETED</code>)；完成后取消项目 / 任务均被拦截 <code>ILLEGAL_PROJECT_TRANSITION</code> / <code>ILLEGAL_TASK_TRANSITION</code></p><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-pms-app</code>（含 README 与 E2E 脚本）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>与工单 / MES 共同坐实「百套流水线」可复制：独立工程 + 选定 <code>openbiz-*</code> 构件 + 自建 Mapper / Service。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',13)])])}const b=o(d,[["render",i]]);export{_ as __pageData,b as default};
